import SwiftUI

struct AppCard: View { let app: LabApp; let action: () -> Void; var body: some View { Button(action: action) { VStack(alignment: .leading, spacing: 14) { ZStack { RoundedRectangle(cornerRadius: 20).fill(app.accent.gradient); Image(systemName: app.symbol).font(.system(size: 34)).foregroundStyle(.white).frame(maxWidth: .infinity, minHeight: 110) }; Text(app.name).font(.headline); Text(app.purpose).font(.caption).foregroundStyle(.secondary).multilineTextAlignment(.leading); Label(app.available ? "Installed" : "Unavailable", systemImage: app.available ? "checkmark.circle.fill" : "circle.dashed").font(.caption2).foregroundStyle(app.available ? .green : .secondary) }.padding(12).background(.regularMaterial, in: RoundedRectangle(cornerRadius: 24)) }.buttonStyle(.plain).accessibilityLabel("\(app.name), \(app.purpose), \(app.available ? "installed" : "unavailable")") }
}

struct AppLaunchSheet: View { let app: LabApp; let launch: () -> Void; @Environment(\.dismiss) private var dismiss; var body: some View { VStack(spacing: 18) { Image(systemName: app.symbol).font(.system(size: 52)).foregroundStyle(app.accent); Text(app.name).font(.largeTitle.bold()); Text(app.purpose).font(.title3).multilineTextAlignment(.center).foregroundStyle(.secondary); if app.available { Button("Open (app.name)", action: launch).buttonStyle(.borderedProminent).controlSize(.large) } else { Text("Install this app on your iPhone to open it from MaxLab.").multilineTextAlignment(.center).foregroundStyle(.secondary) }; Button("Close", action: { dismiss() }).buttonStyle(.bordered) }.padding(32).presentationDetents([.medium]) } }
